// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address ownerAddr, address newAllo) public {
        vm.assume(ownerAddr != address(0));

        c.initialize();

        c.transferOwnership(ownerAddr);

        vm.prank(ownerAddr);
        bool ok;
        try c.updateAlloSettings(newAllo) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!(ok) == false || c.alloSettings() == newAllo);
    }
}
